def coalesce_ranges(values: list[tuple[int,int]]) -> list[tuple[int,int]] | None:
    if any(type(a) is not int or type(b) is not int or a>=b for a,b in values): return None
    out=[]
    for a,b in sorted(values):
        if not out or a>out[-1][1]:out.append((a,b))
        else:out[-1]=(out[-1][0],max(out[-1][1],b))
    return out
